suppressPackageStartupMessages(library(tidyverse))
out<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1])))
src<-'./output/research_extensions/28_paper_state_guarded_refresh'
a<-read_csv(file.path(src,'all_event_study.csv'),show_col_types=FALSE)%>%filter(analysis%in%c('primary/emp_pop_ratio','primary/rac_total'),outcome%in%c('emp_pop_ratio','primary_emp_pop_ratio','log_rac','log_primary_rac'))
b<-read_csv(file.path(src,'primary_wac/comparison/event_study.csv'),show_col_types=FALSE)%>%filter(outcome%in%c('log_wac','log_primary_wac'))
d<-bind_rows(a,b)%>%filter(specification=='matched_pair_year')%>%mutate(event=as.numeric(sub('year::','',term)),definition=if_else(str_detect(outcome,'primary'),'Primary jobs','All jobs'),measure=case_when(str_detect(outcome,'emp_pop')~'Employment-to-population ratio (pp)',str_detect(outcome,'rac')~'Resident-held jobs (log)',TRUE~'Workplace jobs (log)'))%>%filter(between(event,-5,5))
d<-d%>%mutate(estimate=estimate*if_else(str_detect(outcome,'emp_pop'),100,1),std_error=std_error*if_else(str_detect(outcome,'emp_pop'),100,1))
d<-bind_rows(d,distinct(d,group,definition,measure)%>%mutate(event=-1,estimate=0,std_error=0))%>%mutate(group=factor(group,levels=c('pooled','lower_income','higher_income'),labels=c('Pooled','Lower income','Higher income')),measure=factor(measure,levels=c('Employment-to-population ratio (pp)','Resident-held jobs (log)','Workplace jobs (log)')))
stopifnot(nrow(distinct(d,group,measure,definition))==18,!anyDuplicated(d[c('group','measure','definition','event')]))
p<-ggplot(d,aes(event,estimate,colour=definition,group=definition))+geom_hline(yintercept=0,colour='grey55',linewidth=.4)+geom_vline(xintercept=-1,linetype=2,colour='grey65')+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.08,linewidth=.4,position=position_dodge(.12))+geom_line(linewidth=.5)+geom_point(size=1.5)+facet_grid(measure~group,scales='free_y',switch='y')+scale_color_manual(values=c('#969da5','#214F80'))+scale_x_continuous(breaks=c(-5,-3,-1,0,2,4,5))+theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#e1e7ef',linetype='dotted'),strip.background=element_blank(),strip.text=element_text(face='bold',colour='#214F80'),strip.placement='outside',panel.border=element_rect(colour='#c5cfdc'),legend.position='bottom',legend.title=element_blank(),panel.spacing.y=grid::unit(.5,'cm'))+labs(x='Years relative to first placement',y=NULL)
for(ext in c('png','pdf'))ggsave(file.path(out,paste0('primary_comparison.',ext)),p,width=13,height=10,dpi=180)
write_csv(d,file.path(out,'primary_comparison_plotted.csv'))
